 19→// Transcript message type constants - aliases to transcript package for local use.
 20→const (
 21→	transcriptTypeUser = transcript.TypeUser
 22→)
 23→
 24→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 25→// Computes the path dynamically from the current repo location for cross-machine portability.
 26→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 27→	repoRoot, err := paths.WorktreeRoot(ctx)
 28→	if err != nil {
 29→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 30→	}
 31→
 32→	sessionDir, err := agent.GetSessionDir(repoRoot)
 33→	if err != nil {
 34→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 35→	}
 36→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 37→}
 38→
 39→// agentSessionBaseDirs maps agent names to the base directories that contain
 40→// per-project session subdirectories. Each agent organizes transcripts under
 41→// a per-project subdirectory within its base dir.
 42→var agentSessionBaseDirs = map[types.AgentName]func() (string, error){
 43→	agentpkg.AgentNameClaudeCode: func() (string, error) {
 44→		home, err := os.UserHomeDir()
 45→		if err != nil {
 46→			return "", fmt.Errorf("failed to get home directory: %w", err)
 47→		}
 48→		return filepath.Join(home, ".claude", "projects"), nil
 49→	},
 50→	agentpkg.AgentNameGemini: func() (string, error) {
 51→		home, err := os.UserHomeDir()
 52→		if err != nil {
 53→			return "", fmt.Errorf("failed to get home directory: %w", err)
 54→		}
 55→		return filepath.Join(home, ".gemini", "tmp"), nil
 56→	},
 57→}
 58→
 59→// searchTranscriptInProjectDirs searches for a session transcript across all of an agent's
 60→// project directories. Agents like Claude Code and Gemini CLI use the cwd to determine the
 61→// project directory, so the transcript may be stored under a different project directory
 62→// if the session was started from a different working directory.
 63→func searchTranscriptInProjectDirs(agentName types.AgentName, sessionID string, ag agentpkg.Agent) (string, error) {
 64→	baseDirFn, ok := agentSessionBaseDirs[agentName]
 65→	if !ok {
 66→		return "", fmt.Errorf("fallback transcript search not supported for agent %q", agentName)
 67→	}
 68→	baseDir, err := baseDirFn()
 69→	if err != nil {
 70→		return "", fmt.Errorf("failed to get base directory: %w", err)
 71→	}
 72→
 73→	// Walk all subdirectories looking for the session file.
 74→	// Agents like Gemini nest chats under <project>/chats/, so we need recursive search.
 75→	var found string
 76→	walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
 77→		if err != nil || !d.IsDir() {
 78→			return nil //nolint:nilerr // skip inaccessible dirs
 79→		}
 80→		candidate := ag.ResolveSessionFile(path, sessionID)
 81→		if _, statErr := os.Stat(candidate); statErr == nil {
 82→			found = candidate
 83→			return filepath.SkipAll
 84→		}
 85→		return nil
 86→	})
 87→	if walkErr != nil {
 88→		return "", fmt.Errorf("failed to search project directories: %w", walkErr)
 89→	}
 90→	if found != "" {
 91→		return found, nil
 92→	}
 93→	return "", errors.New("transcript not found in any project directory")
 94→}
