 96→// AgentTranscriptPath returns the path to a subagent's transcript file.
 97→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
 98→// as the main transcript.
 99→func AgentTranscriptPath(transcriptDir, agentID string) string {
100→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
101→}
