103→// toolResultBlock represents a tool_result in a user message
104→type toolResultBlock struct {
105→	Type      string `json:"type"`
106→	ToolUseID string `json:"tool_use_id"`
107→}
108→
109→// userMessageWithToolResults represents a user message that may contain tool results
110→type userMessageWithToolResults struct {
111→	Content []toolResultBlock `json:"content"`
112→}
113→
114→// FindCheckpointUUID finds the UUID of the message containing the tool_result
115→// for the given tool_use_id. This is used to find the checkpoint point for
116→// transcript truncation when rewinding to a task.
117→// Returns the UUID and true if found, empty string and false otherwise.
118→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
119→	for _, line := range transcript {
120→		if line.Type != transcriptTypeUser {
121→			continue
122→		}
123→
124→		var msg userMessageWithToolResults
125→		if err := json.Unmarshal(line.Message, &msg); err != nil {
126→			continue
127→		}
128→
129→		for _, block := range msg.Content {
130→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
131→				return line.UUID, true
132→			}
133→		}
134→	}
135→	return "", false
136→}
137→
138→// TruncateTranscriptAtUUID returns transcript lines up to and including the
139→// line with the given UUID. If the UUID is not found or is empty, returns
140→// the entire transcript.
141→//
142→//nolint:revive // Exported for testing purposes
143→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
144→	if uuid == "" {
145→		return transcript
146→	}
147→
148→	for i, line := range transcript {
149→		if line.UUID == uuid {
150→			return transcript[:i+1]
151→		}
152→	}
153→
154→	// UUID not found, return full transcript
155→	return transcript
156→}
