// searchTranscriptInProjectDirs searches for a session transcript across all of an agent's
// project directories. Agents like Claude Code and Gemini CLI use the cwd to determine the
// project directory, so the transcript may be stored under a different project directory
// if the session was started from a different working directory.
func searchTranscriptInProjectDirs(agentName types.AgentName, sessionID string, ag agentpkg.Agent) (string, error) {
	baseDirFn, ok := agentSessionBaseDirs[agentName]
	if !ok {
		return "", fmt.Errorf("fallback transcript search not supported for agent %q", agentName)
	}
	baseDir, err := baseDirFn()
	if err != nil {
		return "", fmt.Errorf("failed to get base directory: %w", err)
	}

	// Walk all subdirectories looking for the session file.
	// Agents like Gemini nest chats under <project>/chats/, so we need recursive search.
	var found string
	walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
		if err != nil || !d.IsDir() {
			return nil //nolint:nilerr // skip inaccessible dirs
		}
		candidate := ag.ResolveSessionFile(path, sessionID)
		if _, statErr := os.Stat(candidate); statErr == nil {
			found = candidate
			return filepath.SkipAll
		}
		return nil
	})
	if walkErr != nil {
		return "", fmt.Errorf("failed to search project directories: %w", walkErr)
	}
	if found != "" {
		return found, nil
	}
	return "", errors.New("transcript not found in any project directory")
}

