// normalizeGeminiTranscript re-serializes a Gemini JSON transcript so that all
// content fields are plain strings. Gemini user messages store content as
// [{"text":"..."}] arrays, but the UI expects string content. Parsing through
// geminicli.ParseTranscript normalizes this via GeminiMessage.UnmarshalJSON.
func normalizeGeminiTranscript(data []byte) ([]byte, error) {
	parsed, err := geminicli.ParseTranscript(data)
	if err != nil {
		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
	}
	normalized, err := json.MarshalIndent(parsed, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("failed to re-serialize Gemini transcript: %w", err)
	}
	return normalized, nil
}

